import {models,categories,palette,snapshot} from './models.js';
import {architecture,buildGraph,tensorShape,tensorSize,formatBytes} from './graph.js';
import {GraphCanvas} from './renderer.js';
import {attention,sampleMatrices} from './math.js';

const icons={logo:'M4 20 12 4l8 16M7 14h10M12 4v16',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',layers:'m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5',arrow:'M5 12h14m-6-6 6 6-6 6',external:'M14 3h7v7m0-7L10 14M10 3H4v17h17v-6',code:'m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18',plus:'M12 5v14M5 12h14',minus:'M5 12h14',fit:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M9 9h6v6H9z',play:'m8 4 13 8-13 8V4Z',pause:'M8 5v14M16 5v14',next:'m5 5 10 7-10 7V5ZM19 5v14',prev:'m19 5-10 7 10 7V5ZM5 5v14',close:'m6 6 12 12M6 18 18 6',help:'M9 8a3 3 0 1 1 4 3c-1 .5-1 1-1 3m0 3v.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'m5 12 4 4L19 6',menu:'M3 6h18M3 12h18M3 18h18',panel:'M3 3h18v18H3V3Zm12 0v18',cube:'m12 2 10 5v10l-10 5-10-5V7l10-5Zm0 10L2 7m10 5L22 7m-10 5v10',grid:'M3 3h7v7H3V3Zm11 0h7v7h-7V3ZM3 14h7v7H3v-7Zm11 0h7v7h-7v-7',bolt:'m13 2-9 12h7l-1 8 10-13h-7l1-7',branch:'M6 3v12a4 4 0 0 0 4 4h8M6 9h8a4 4 0 0 0 4-4V3',back:'m12 5-7 7 7 7M5 12h15'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.layers}"/></svg>`;
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial=new URL(location.href).searchParams;
const initialModel=models.find(m=>m.id===initial.get('model'))||models.find(m=>m.id==='pi05');
const state={model:initialModel,level:Math.min(3,Math.max(0,Number(initial.get('level'))||0)),tab:'explain',mode:'tensor',focus:{module:'language',layer:0},selected:null,step:0,playing:false,params:{batch:1,tokens:16,horizon:initialModel.horizon,actionDim:initialModel.actionDim},search:''};
let graph,renderer,playTimer,toastTimer;

$('#app').innerHTML=`
<header class="topbar"><div class="top-left"><button class="quiet mobile-button catalog-toggle" id="catalog-toggle" aria-label="打开模型目录">${icon('menu')}</button><div class="brand"><span class="brand-mark">${icon('logo')}</span>Model Atlas</div><span class="top-label">模型架构可视化</span></div><div class="top-actions"><span class="version">RESEARCH SNAPSHOT ${snapshot}</span><button class="quiet" id="open-lab">${icon('bolt')}<span class="button-label">计算实验室</span></button><button class="quiet icon-button" id="open-help" aria-label="使用说明">${icon('help')}</button></div></header>
<div class="workspace">
 <aside class="catalog" id="catalog" aria-label="模型目录"><div class="catalog-heading"><span>模型目录</span><span class="count">${models.length}</span><button class="quiet icon-button mobile-close" id="catalog-close" aria-label="关闭目录">${icon('close')}</button></div><div class="model-search">${icon('search')}<input type="search" id="model-search" placeholder="搜索模型或架构…" aria-label="搜索模型"></div><nav class="model-list" id="model-list"></nav><div class="catalog-footer">架构与公开配置 · ${snapshot}<br><a href="https://bbycroft.net/llm" target="_blank" rel="noopener noreferrer">交互灵感：Brendan Bycroft ↗</a></div></aside>
 <main class="surface"><section class="model-header" id="model-header"></section>
  <div class="viewbar"><div class="segments" aria-label="架构展开层级"><button data-level="0">架构全景</button><button data-level="1">网络层</button><button data-level="2">算子</button></div><div class="view-actions"><button class="all-button" id="expand-all" title="展开所有已建模层与算子">${icon('layers')}全部展开</button><button class="icon-button view-switch" id="view-switch" aria-label="切换平面计算图" title="切换平面 / 立体">${icon('cube')}</button><button class="icon-button mobile-button inspector-toggle" id="inspector-toggle" aria-label="查看节点详情">${icon('panel')}</button></div></div>
  <div class="canvas-area" id="canvas-area"><canvas id="graph-canvas" tabindex="0" role="img" aria-label="交互模型计算图。拖动平移，滚轮或双指缩放，方向键浏览节点，Enter 展开节点。也可使用详情面板中的节点选择器。"></canvas><div class="canvas-labels"><strong id="scene-title"></strong><span id="scene-subtitle"></span></div><div class="legend"><span><i style="--color:${palette.vision}"></i>视觉</span><span><i style="--color:${palette.attention}"></i>注意力</span><span><i style="--color:${palette.mlp}"></i>前馈</span><span><i style="--color:${palette.action}"></i>动作</span></div><div class="canvas-nav"><button class="icon-button" id="zoom-out" aria-label="缩小">${icon('minus')}</button><output id="zoom-value">100%</output><button class="icon-button" id="zoom-in" aria-label="放大">${icon('plus')}</button><button class="icon-button" id="fit" aria-label="适应画布" title="适应画布 (F)">${icon('fit')}</button></div><div class="tooltip hide" id="node-tooltip"></div></div>
  <footer class="timeline"><div class="playback"><button class="play" id="play" aria-label="播放计算路径">${icon('play')}</button><button class="quiet icon-button" id="prev" aria-label="上一步">${icon('prev')}</button><div class="timeline-track" id="timeline-track"></div><button class="quiet icon-button" id="next" aria-label="下一步">${icon('next')}</button><span class="playback-text" id="step-counter"></span></div><div class="timeline-note"><strong id="step-label"></strong><span>路径演示 · 未加载模型权重</span></div></footer>
 </main>
 <aside class="inspector" id="inspector" aria-label="计算节点详情"><div class="inspector-top"><span>计算节点</span><div style="display:flex;gap:4px"><span class="count" id="node-count"></span><button class="quiet icon-button mobile-close" id="inspector-close" aria-label="关闭详情">${icon('close')}</button></div></div><div class="inspector-tabs" role="tablist" aria-label="节点详情"><button role="tab" data-tab="explain">解释</button><button role="tab" data-tab="tensor">张量</button><button role="tab" data-tab="source">来源</button></div><div class="inspector-body" id="inspector-body"></div><div class="inspector-bottom"><span>符号计算图</span><button class="quiet" id="scope-help" style="padding:3px 0;font-size:12px">覆盖范围 ${icon('external')}</button></div></aside>
</div><dialog id="main-dialog" aria-labelledby="dialog-title"></dialog><div id="toast" class="toast hide" role="status"></div>`;

function renderCatalog(){const q=state.search.trim().toLowerCase();const visible=models.filter(m=>[m.name,m.short,m.maker,m.kind,m.group,m.description].join(' ').toLowerCase().includes(q));$('#model-list').innerHTML=categories.map(([group,label])=>{const list=visible.filter(m=>m.group===group);if(!list.length)return '';return `<div class="group-heading">${group} <span style="letter-spacing:0;font-family:inherit">${label}</span></div>${list.map(m=>`<button class="model-button ${m.id===state.model.id?'active':''}" data-model="${m.id}" aria-current="${m.id===state.model.id?'true':'false'}"><span class="model-name-row">${esc(m.name)}${m.id===state.model.id?'<i class="model-mark"></i>':''}</span><span class="model-meta">${esc(m.params)} <span>·</span> ${m.openness==='论文架构'?'论文架构':esc(m.active)}</span></button>`).join('')}`}).join('')||'<p class="empty">没有匹配的模型。可搜索 π、Qwen、MoE 或 SONIC。</p>';}
function renderHeader(){const m=state.model;const stats=m.group==='LLM'?[['参数规模',m.params],['激活参数',m.active],['网络深度',m.layers+' layers'],['隐藏维度',m.d.toLocaleString()]]:[['参数规模',m.params],['模型类型',m.kind==='sonic'?'全身控制':m.kind==='wam'?'视频 + 动作':m.kind==='fast'||m.kind==='openvla'?'自回归动作':'Flow matching'],['主干 / 动作层',`${m.layers||'—'} / ${m.alayers||'—'}`],['开放范围',m.openness]];
 $('#model-header').innerHTML=`<div class="eyebrow">${esc(m.maker.toUpperCase())} <span style="color:#54616a;margin:0 6px">/</span> ARCHITECTURE EXPLORER</div><div class="title-row"><h1>${esc(m.name)}<span class="family-label">${m.group}</span></h1></div><p class="model-description">${esc(m.description)}</p><div class="stats">${stats.map(([label,value])=>`<div class="stat"><span>${label}</span><strong>${esc(value)}</strong></div>`).join('')}</div>`;document.title=`${m.short} · Model Atlas`;}
function updateURL(){const url=new URL(location.href);url.searchParams.set('model',state.model.id);url.searchParams.set('level',state.level);history.replaceState(null,'',url);}
function changeModel(id){const m=models.find(m=>m.id===id);if(!m)return;pause();state.model=m;state.focus={module:m.group==='Control'?'decoder':m.kind==='wam'?'joint':'language',layer:0};state.params={batch:1,tokens:16,horizon:m.horizon||50,actionDim:m.actionDim||32};state.step=0;state.selected=null;state.tab='explain';renderCatalog();renderHeader();rebuild();$('#catalog').classList.remove('open');}
function changeLevel(level){pause();state.level=level;state.step=0;state.selected=null;rebuild();if(level===3)toast('已展开全部已建模层与算子；缩放或通过节点选择器定位。');}
function rebuild(){const canExpand=architecture(state.model).some(n=>n.stack&&n.depth);if(!canExpand&&(state.level===1||state.level===2))state.level=0;$$('[data-level]').forEach(b=>{b.disabled=!canExpand&&Number(b.dataset.level)>0;b.title=b.disabled?'此模型当前只有已核实的模块图':''});graph=buildGraph(state.model,state.level,state.focus);const preferred=state.level===0?graph.nodes.find(n=>n.id==='action'||n.id==='language'||n.id==='joint'||n.id==='decoder'):graph.nodes.find(n=>n.module===state.focus.module&&n.layer===state.focus.layer);state.selected=graph.map.has(state.selected)?state.selected:preferred?.id||graph.nodes[0]?.id;state.step=Math.max(0,graph.nodes.findIndex(n=>n.id===state.selected));renderer.setGraph(graph);renderer.select(state.selected);for(const b of $$('[data-level]')){b.classList.toggle('active',Number(b.dataset.level)===state.level);b.setAttribute('aria-pressed',String(Number(b.dataset.level)===state.level))}$('#expand-all').classList.toggle('active',state.level===3);$('#expand-all').setAttribute('aria-pressed',String(state.level===3));$('#scene-title').textContent=['MODEL OVERVIEW','LAYER EXPLORER','OPERATOR GRAPH','EXPANDED COMPUTATION GRAPH'][state.level];$('#scene-subtitle').textContent=`${graph.nodes.length.toLocaleString()} 个节点 · ${graph.edges.length.toLocaleString()} 条路径${state.level===3?' · E 轴批量表示专家':''}`;$('#node-count').textContent=graph.nodes.length.toLocaleString()+' nodes';updateInspector();updateTimeline();updateURL();}
function selectNode(n,focus=false){if(!n)return;state.selected=n.id;state.step=graph.nodes.findIndex(x=>x.id===n.id);renderer.select(n.id);if(focus)renderer.focus(n.id);updateInspector();updateTimeline();}
function drill(n){if(!n)return;const s=graph.arch.find(s=>s.id===n.module);if(s?.stack&&s.depth){state.focus={module:s.id,layer:n.layer||0};changeLevel(2);return}if(state.level===0&&graph.arch.some(s=>s.stack&&s.depth)){state.focus={module:graph.arch.find(s=>s.stack&&s.depth).id,layer:0};changeLevel(1);return}state.tab='explain';updateInspector();$('#inspector').classList.add('open');if(n.opaque)toast('该模块保持语义层级；内部配置尚未核实。');}
function evidenceHTML(n){const paper=state.model.evidence==='paper'||n.opaque;const label=n.external?'模型外的控制环节':n.opaque?'语义模块 · 内部算子未全部核实':state.model.evidence==='code'?'公开代码结构 · 手工数学图':state.model.evidence==='config'?'公开配置尺寸 · 手工数学图':'论文 / 官方说明 · 语义结构';return `<div class="evidence ${paper?'paper':''}">${icon(n.opaque?'help':'check')}<span>${label}</span></div>`;}
function nodeSelector(){return `<label class="caption" for="node-select">定位节点（也可使用方向键）</label><select class="node-select" id="node-select">${graph.nodes.map((n,i)=>`<option value="${esc(n.id)}" ${n.id===state.selected?'selected':''}>${i+1}. ${n.layer!==undefined&&state.level>0?'L'+(n.layer+1)+' · ':''}${esc(n.label)}</option>`).join('')}</select>`;}
function layerSelector(n){const modules=graph.arch.filter(s=>s.stack&&s.depth);if(!modules.length||state.level===0)return '';const s=modules.find(s=>s.id===n.module)||modules[0];return `<div class="input-row"><label for="module-select">网络模块</label><select class="node-select" id="module-select" style="width:155px;margin:0">${modules.map(s2=>`<option value="${s2.id}" ${s2.id===s.id?'selected':''}>${esc(s2.label)}</option>`).join('')}</select></div><div class="input-row"><label for="layer-select">层索引</label><select id="layer-select" class="node-select" style="width:110px;margin:0">${Array.from({length:s.depth},(_,i)=>`<option value="${i}" ${i===(n.layer||0)?'selected':''}>${i+1} / ${s.depth}</option>`).join('')}</select></div>`;}
function updateInspector(){const n=graph.map.get(state.selected)||graph.nodes[0];if(!n)return;const m=state.model;$$('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===state.tab);b.setAttribute('aria-selected',String(b.dataset.tab===state.tab))});const shape=tensorShape(n.shape||[],state.params,m),size=tensorSize(shape);
 const common=`${nodeSelector()}<div class="bread">${esc(m.short)} <span>/</span> ${state.level===0?'架构':state.level===1?'网络层':'算子'}</div><div class="node-tag" style="color:${n.color}"><i></i>${esc(n.type.toUpperCase())}${n.external?' · EXTERNAL':''}</div><h2>${esc(n.label)}</h2><div class="caption">${esc(n.id)}${n.layer!==undefined&&state.level>0?' · layer '+(n.layer+1):''}</div>`;
 let content='';
 if(state.tab==='explain'){
  const incoming=graph.edges.filter(e=>e.to===n.id),outgoing=graph.edges.filter(e=>e.from===n.id);const canDrill=graph.arch.some(s=>s.id===n.module&&s.stack&&s.depth);
  content=`<p class="node-description">${esc(n.desc||'该节点在计算路径中承接上游输入，并把输出传递给下游模块。')}</p>${n.formula?`<h3>计算关系</h3><div class="formula">${esc(n.formula)}</div>`:''}<h3>张量与连接</h3><dl class="meta-table"><dt>输出形状</dt><dd>${shape.length?esc(shape.join(' × ')):'依输入而定'}</dd><dt>数据类型</dt><dd>${n.id==='tokens'?'整数 ID':'BF16 示例'}</dd><dt>输入 / 输出边</dt><dd>${incoming.length} / ${outgoing.length}</dd>${n.depth?`<dt>重复层数</dt><dd>${n.depth}</dd>`:''}${state.model.experts&&n.type==='mlp'?`<dt>路由专家</dt><dd>${m.topk} / ${m.experts}</dd>`:''}</dl>${evidenceHTML(n)}${layerSelector(n)}${canDrill&&state.level!==2?`<button class="full-width" id="drill-node">${icon('branch')}展开内部算子 ${icon('arrow')}</button>`:''}${n.lab?`<button class="full-width" id="node-lab">${icon('bolt')}用小矩阵计算这个算子</button>`:''}<p class="subtle-note">${esc(graph.modeNote)}</p>`;
 }else if(state.tab==='tensor'){
  content=`<h3>输出张量</h3><div class="formula">[ ${esc(shape.join(', '))||'shape not resolved'} ]</div><div class="tensor-grid" aria-hidden="true">${Array.from({length:32},(_,i)=>`<div class="tensor-cell" style="opacity:${.2+(i%8)/12}"></div>`).join('')}</div><p class="caption">网格表示张量的存在与维度，格子不表示真实激活值。</p><dl class="meta-table"><dt>元素数</dt><dd>${size?size.elements.toLocaleString():'含未确定维度'}</dd><dt>BF16 单张量容量</dt><dd>${size?formatBytes(size.bytes):'—'}</dd></dl><h3>形状计算参数</h3><p class="caption">下列值用于形状推演，不修改 checkpoint 或执行模型。</p><div class="input-row"><label for="batch-input">批大小 B</label><input type="number" id="batch-input" value="${state.params.batch}" min="1" max="64"></div><div class="input-row"><label for="tokens-input">前缀长度 T</label><input type="number" id="tokens-input" value="${state.params.tokens}" min="1" max="1048576"></div>${m.group!=='LLM'?`<div class="input-row"><label for="horizon-input">动作块 H</label><input type="number" id="horizon-input" value="${state.params.horizon}" min="1" max="512"></div><div class="input-row"><label for="action-input">填充动作维 A</label><input type="number" id="action-input" value="${state.params.actionDim}" min="1" max="256"></div>`:''}<p class="subtle-note">P：图像 patch 数；E：专家数；D：未核实的隐藏维。容量仅为此张量按 2 bytes/元素估算，不等于显存峰值；FlashAttention 可不物化注意力矩阵。</p><button class="full-width" id="node-lab">${icon('bolt')}打开数值计算实验</button>`;
 }else{
  content=`${evidenceHTML(n)}<h3>官方资料</h3>${m.source.map(([title,url])=>`<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(title)} ↗<span>${new URL(url).hostname}</span></a>`).join('')}<h3>当前覆盖范围</h3><p class="node-description">${esc(m.limit)}</p><p class="subtle-note">核查日期 ${snapshot}。来源页面可能更新；明确指定 revision 的链接才是固定快照。所有图都为人工整理的数学结构，尚未接入 PyTorch / ONNX 自动追踪或真实模型权重。</p>`;
 }
 $('#inspector-body').innerHTML=common+content;
 $('#node-select').addEventListener('change',e=>{pause();selectNode(graph.map.get(e.target.value),true)});
 $('#drill-node')?.addEventListener('click',()=>drill(n));$('#node-lab')?.addEventListener('click',showLab);
 $('#module-select')?.addEventListener('change',e=>{state.focus={module:e.target.value,layer:0};if(state.level===2){rebuild()}else selectNode(graph.nodes.find(n=>n.module===e.target.value),true)});
 $('#layer-select')?.addEventListener('change',e=>{state.focus={module:$('#module-select').value,layer:Number(e.target.value)};if(state.level===2)rebuild();else selectNode(graph.nodes.find(n=>n.module===state.focus.module&&n.layer===state.focus.layer),true)});
 for(const [id,key,max] of [['batch-input','batch',64],['tokens-input','tokens',1048576],['horizon-input','horizon',512],['action-input','actionDim',256]])$('#'+id)?.addEventListener('change',e=>{const value=Number(e.target.value);if(!Number.isInteger(value)||value<1||value>max){e.target.value=state.params[key];toast(`请输入 1–${max} 之间的整数。`);return}state.params[key]=value;updateInspector()});
}
function updateTimeline(){const total=graph.nodes.length,index=Math.max(0,state.step);const ticks=Math.min(36,total);$('#timeline-track').innerHTML=Array.from({length:ticks},(_,i)=>{const idx=Math.round(i*(total-1)/Math.max(1,ticks-1));const progress=index/Math.max(1,total-1)*(ticks-1);return `<button class="timeline-tick ${i<=progress?'done':''} ${i===Math.round(progress)?'current':''}" data-step="${idx}" aria-label="跳转计算节点 ${idx+1}"></button>`}).join('');$('#step-counter').textContent=`${String(index+1).padStart(2,'0')} / ${total}`;$('#step-label').textContent=graph.nodes[index]?.label||'';$('#prev').disabled=index===0;$('#next').disabled=index===total-1;}
function step(delta,follow=true){const idx=Math.max(0,Math.min(graph.nodes.length-1,state.step+delta));selectNode(graph.nodes[idx],follow&&state.level>0);if(idx===graph.nodes.length-1)pause();}
function play(){if(state.playing){pause();return}if(state.step>=graph.nodes.length-1)state.step=-1;state.playing=true;$('#play').innerHTML=icon('pause');$('#play').setAttribute('aria-label','暂停计算路径');step(1);playTimer=setInterval(()=>step(1),1100)}
function pause(){state.playing=false;clearInterval(playTimer);$('#play').innerHTML=icon('play');$('#play').setAttribute('aria-label','播放计算路径')}
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.remove('hide');toastTimer=setTimeout(()=>$('#toast').classList.add('hide'),4000)}
function showDialog(title,body){pause();const d=$('#main-dialog');d.innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${title}</h2><button id="close-dialog" class="quiet icon-button" aria-label="关闭">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;$('#close-dialog').onclick=()=>d.close();if(!d.open)d.showModal();d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}};}
function showHelp(){showDialog('理解架构，从全景到计算',`<p>Model Atlas 将语言、视觉动作、世界动作与全身控制模型放在同一个可探索工作台。</p><dl class="help-list"><dt>架构全景</dt><dd>查看输入、各网络模块、输出以及条件与反馈路径。</dd><dt>网络层</dt><dd>按已核实的深度展开每层，点击或双击进入内部。</dd><dt>算子</dt><dd>查看指定层的 Q/K/V、掩码、Softmax、前馈门控和残差路径。</dd><dt>全部展开</dt><dd>一次建立全部已建模层的计算图。循环保留为回边，MoE 使用 E 轴批量表示专家；不逐元素铺开数十亿个参数。</dd></dl><div class="scope-box"><p><strong>计算图、真实激活与数值示例是三件不同的事。</strong><br>本版图谱依据公开资料人工建模。灰色 ◇ 节点为内部未完全核实的语义模块。没有连接真实 checkpoint 推理；计算实验室用明确给出的教学矩阵，在浏览器内计算真实数值结果。</p></div><h3>操作</h3><dl class="help-list"><dt>平移 / 缩放</dt><dd>拖动画布；滚轮或双指缩放；右下角按钮同样可用。</dd><dt>节点详情</dt><dd>单击节点；小屏幕点击右侧面板按钮。所有节点也可通过下拉框选择。</dd><dt>键盘</dt><dd>聚焦画布后，方向键浏览，Enter 展开，+ / − 缩放，F 适应画布。</dd><dt>立体 / 平面</dt><dd>立体模式以张量块表现结构，平面模式强调依赖边。格子不表示真实激活。</dd></dl><p>交互参考 <a href="https://bbycroft.net/llm" target="_blank" rel="noopener noreferrer">Brendan Bycroft 的 LLM Visualization</a>。模型来源与具体覆盖范围在每个模型的“来源”页中列出。</p>`)}
let lab={...sampleMatrices(),causal:true,temperature:1,row:2};
function showLab(){lab={...sampleMatrices(),causal:true,temperature:1,row:2};showDialog('计算实验室 · Scaled dot-product attention',`<p>4 个 token，单头，dₖ = 3。可修改 Q / K / V 中任意数值，查看点积、掩码、Softmax 和加权输出。<strong>这是独立教学示例，数值不是 ${esc(state.model.short)} 的权重或激活。</strong></p><div class="lab-controls"><label><input type="checkbox" id="causal-mask" checked> 因果掩码</label><label>温度 τ <input type="range" id="temperature" min="0.1" max="3" step="0.1" value="1"><output id="temperature-value">1.0</output></label><label for="query-row">Query 行 <select id="query-row" class="node-select" style="width:100px;margin:0">${[0,1,2,3].map(i=>`<option value="${i}" ${i===2?'selected':''}>token ${i+1}</option>`).join('')}</select></label></div><div class="lab-matrices">${['Q','K','V'].map(k=>`<div class="matrix-block"><h3>${k} <span class="caption">4 × 3 · 可编辑</span></h3><div class="matrix" style="grid-template-columns:repeat(3,1fr)">${lab[k].flatMap((r,i)=>r.map((v,j)=>`<input type="number" step="0.1" min="-10" max="10" value="${v}" data-matrix="${k}" data-i="${i}" data-j="${j}" aria-label="${k} 行 ${i+1} 列 ${j+1}">`)).join('')}</div></div>`).join('')}</div><div id="lab-results"></div><p class="subtle-note">此示例从 Q/K/V 开始，不包含分词、embedding 或 QKV 权重投影；先除以 √3，再除以温度，屏蔽位置设为 −∞，使用数值稳定的 Softmax。</p>`);
 $('[id=causal-mask]').onchange=e=>{lab.causal=e.target.checked;renderLab()};$('#temperature').oninput=e=>{lab.temperature=Number(e.target.value);$('#temperature-value').textContent=lab.temperature.toFixed(1);renderLab()};$('#query-row').onchange=e=>{lab.row=Number(e.target.value);renderLab()};$$('[data-matrix]').forEach(input=>input.onchange=e=>{const v=Number(e.target.value);if(!Number.isFinite(v)||Math.abs(v)>10||e.target.value===''){e.target.value=lab[e.target.dataset.matrix][e.target.dataset.i][e.target.dataset.j];return}lab[e.target.dataset.matrix][e.target.dataset.i][e.target.dataset.j]=v;renderLab()});renderLab();}
function renderLab(){const result=attention(lab.Q,lab.K,lab.V,lab),i=lab.row;const grid=(matrix,prob=false)=>`<div class="matrix" style="grid-template-columns:repeat(4,1fr)">${matrix.flatMap((row,r)=>row.map((v,c)=>`<button class="${r===i?'row-selected':''}" data-query="${r}" title="Query ${r+1} → Key ${c+1}" aria-label="Query ${r+1} Key ${c+1} ${Number.isFinite(v)?v.toFixed(4):'已屏蔽'}" style="background:${prob?`rgba(119,166,81,${.12+v*.5})`:'#20343e'}">${Number.isFinite(v)?v.toFixed(3):'−∞'}</button>`)).join('')}</div>`;
 $('#lab-results').innerHTML=`<div class="lab-bottom"><div class="matrix-block"><h3>QKᵀ / (√3 · τ) + mask</h3>${grid(result.masked)}</div><div class="matrix-block"><h3>Softmax · attention weights</h3>${grid(result.probabilities,true)}</div></div><div class="lab-result">Query ${i+1} 的权重 = [ ${result.probabilities[i].map(x=>x.toFixed(4)).join(', ')} ]<br>权重之和 = ${result.probabilities[i].reduce((a,b)=>a+b,0).toFixed(6)}<br>输出 = Σⱼ P[${i+1}, j] V[j] = [ ${result.output[i].map(x=>x.toFixed(4)).join(', ')} ]</div>`;$$('[data-query]').forEach(b=>b.onclick=()=>{lab.row=Number(b.dataset.query);$('#query-row').value=String(lab.row);renderLab()});}

renderer=new GraphCanvas($('#graph-canvas'),{select:n=>{pause();selectNode(n);if(innerWidth<=700)$('#inspector').classList.add('open')},drill,step:d=>{pause();step(d)},zoom:z=>{$('#zoom-value').textContent=(z<.1?(z*100).toFixed(1):Math.round(z*100))+'%'},hover:(n,p)=>{const tip=$('#node-tooltip');if(!n){tip.classList.add('hide');return}tip.textContent=n.label+(n.stack&&n.depth?` · ${n.depth} layers · 双击展开`:'');tip.style.left=Math.max(5,Math.min(p.x+15,$('#canvas-area').clientWidth-260))+'px';tip.style.top=Math.max(5,p.y-45)+'px';tip.classList.remove('hide')}});
$('#model-search').addEventListener('input',e=>{state.search=e.target.value;renderCatalog()});$('#model-list').addEventListener('click',e=>{const b=e.target.closest('[data-model]');if(b)changeModel(b.dataset.model)});
$$('[data-level]').forEach(b=>b.onclick=()=>changeLevel(Number(b.dataset.level)));$('#expand-all').onclick=()=>changeLevel(state.level===3?0:3);
$$('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;updateInspector()});$('#catalog-toggle').onclick=()=>$('#catalog').classList.toggle('open');$('#catalog-close').onclick=()=>$('#catalog').classList.remove('open');$('#inspector-toggle').onclick=()=>$('#inspector').classList.toggle('open');$('#inspector-close').onclick=()=>$('#inspector').classList.remove('open');
$('#view-switch').onclick=()=>{state.mode=state.mode==='tensor'?'flat':'tensor';renderer.setMode(state.mode);$('#view-switch').innerHTML=icon(state.mode==='tensor'?'cube':'grid');$('#view-switch').setAttribute('aria-label',state.mode==='tensor'?'切换平面计算图':'切换立体张量图')};$('#zoom-in').onclick=()=>renderer.zoomAt(1.3);$('#zoom-out').onclick=()=>renderer.zoomAt(1/1.3);$('#fit').onclick=()=>renderer.fit();$('#play').onclick=play;$('#prev').onclick=()=>{pause();step(-1)};$('#next').onclick=()=>{pause();step(1)};$('#timeline-track').onclick=e=>{const b=e.target.closest('[data-step]');if(b){pause();selectNode(graph.nodes[Number(b.dataset.step)],state.level>0)}};$('#open-help').onclick=showHelp;$('#scope-help').onclick=showHelp;$('#open-lab').onclick=showLab;
document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});window.addEventListener('pagehide',()=>pause());
renderCatalog();renderHeader();renderer.size();rebuild();
